import datetime

def count_digit_appearances(date_str):
    year, month, day = map(int, date_str.split('-'))
    year_str = str(year)
    month_str = str(month)
    day_str = str(day)

    year_counts = [year_str.count(str(i)) for i in range(10)]
    month_counts = [month_str.count(str(i)) for i in range(10)]
    day_counts = [day_str.count(str(i)) for i in range(10)]

    return year_counts + month_counts + day_counts

def is_even(n):
    return n % 2 == 0

def count_even_digit_appearances(year, month, day):
    year_counts = count_digit_appearances(f"{year}{month}{day}")
    month_counts = count_digit_appearances(f"{year}{month}{day}")
    day_counts = count_digit_appearances(f"{year}{month}{day}")

    return all(is_even(count) for count in year_counts + month_counts + day_counts)

def count_valid_dates():
    count = 0
    for year in range(2023):
        for month in range(1, 13):
            for day in range(1, 32):
                if count_even_digit_appearances(year, month, day):
                    count += 1
    return count

print(count_valid_dates())
